<?php
// System flow: one chain of real records across modules, verified in MySQL at each step.
declare(strict_types=1);
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/') . '/api'; $root = dirname(__DIR__, 2); $results = []; $jars = []; $tok = [];
$cfgFile = getenv('LTI_CONFIG'); $cfg = require $cfgFile; $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$one = function ($sql) use ($pdo) { $r = $pdo->query($sql)->fetch(PDO::FETCH_NUM); return $r ? $r[0] : null; };
$worker = function () use ($root, $cfgFile) { return (string)shell_exec('LTI_CONFIG=' . escapeshellarg($cfgFile) . ' php ' . escapeshellarg("$root/server/app/bin/worker.php") . ' --once 2>&1'); };
function rq(string $who, string $m, string $p, $b = null, array $h = []): array { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar'); $ch = curl_init($base . $p); $hd = array_merge(['Accept: application/json'], $h); if (!empty($tok[$who]) && $m !== 'GET') $hd[] = 'X-CSRF-Token: ' . $tok[$who];
  if ($b !== null) { $hd[] = 'Content-Type: application/json'; curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($b)); } curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $m, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $hd, CURLOPT_COOKIEJAR => $jars[$who], CURLOPT_COOKIEFILE => $jars[$who]]);
  $r = curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); return [$c, json_decode((string)$r, true) ?? [], (string)$r]; }
function login(string $who, string $e): void { global $tok; [$c, $d] = rq($who, 'POST', '/auth/login', ['email' => $e, 'password' => 'Dev-Password-2026']); if ($c !== 200) throw new Exception("login $e $c"); $tok[$who] = $d['csrf']; }
function t(string $n, callable $f): void { global $results, $stop; if ($stop) { $results[] = [$n, null, 'NOT RUN — an earlier step in the chain failed']; return; } try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; $stop = true; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
$stop = false; foreach (['own' => 'owner@lti.test', 'adv' => 'advisor@lti.test', 'fin' => 'finance@lti.test', 'trv' => 'traveler@lti.test', 'trv2' => 'traveler2@lti.test'] as $k => $e) login($k, $e);
$shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $adv = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'"); $own = (int)$one("SELECT id FROM users WHERE email='owner@lti.test'"); $F = [];
t('F01 Staff creates a CRM contact', function () use (&$F, $one) { [$c, $d] = rq('adv', 'POST', '/contacts', ['firstName' => 'Ana', 'lastName' => 'Flow', 'email' => 'ana.flow@example.test', 'phone' => '+1 (415) 555-0123']); ok($c === 201, "$c"); $F['c'] = $d['contact']['id'];
  ok($one("SELECT phone_e164 FROM contact_phones WHERE contact_id={$F['c']}") === '+14155550123', 'phone mirror'); return 'contact ' . $F['c'] . ' with normalised phone'; });
t('F02 Contact to trip', function () use (&$F, $shah, $one) { [$c, $d] = rq('adv', 'POST', '/trips', ['name' => 'Kyoto Autumn Flow', 'destination' => 'Kyoto, Japan', 'startDate' => '2027-11-02', 'endDate' => '2027-11-09', 'primaryContactId' => $shah]); ok($c === 201, "$c " . json_encode($d)); $F['t'] = $d['trip']['id'];
  ok((int)$one("SELECT owner_id FROM trips WHERE id={$F['t']}") > 0, 'owner'); return 'trip ' . $F['t']; });
t('F03 Trip to itinerary (days, activities, internal note)', function () use (&$F, $one) { [, $g] = rq('adv', 'GET', "/trips/{$F['t']}/itinerary"); $o = $g['options'][0];
  $o['days'][0]['acts'] = [['id' => 'f-a1', 'type' => 'tour', 'title' => 'Fushimi Inari at dawn', 'inote' => 'INTERNAL margin note', 'cnote' => 'Comfortable shoes']]; $o['days'][] = ['id' => 'f-d2', 't' => 'Arashiyama', 'acts' => [['id' => 'f-a2', 'type' => 'excursion', 'title' => 'Bamboo grove']]];
  [$c] = rq('adv', 'PUT', "/trips/{$F['t']}/itinerary", ['rev' => $g['rev'], 'options' => [$o]]); ok($c === 200, "$c"); $n = (int)$one("SELECT COUNT(*) FROM itinerary_activities a JOIN itinerary_days d ON d.id=a.day_id JOIN itinerary_options o ON o.id=d.option_id WHERE o.trip_id={$F['t']}"); ok($n === 2, "acts $n"); return '2 days, 2 activities in MySQL'; });
t('F04 Trip to booking', function () use (&$F, $one) { [$c1, $s] = rq('own', 'POST', '/suppliers', ['name' => 'Flow Ryokan', 'category' => 'hotel']); ok($c1 === 201, "supplier $c1");
  [$c, $d] = rq('adv', 'POST', '/bookings', ['tripId' => $F['t'], 'supplierId' => $s['supplier']['id'], 'category' => 'accommodation', 'amount' => '1200.00', 'currency' => 'USD']); ok($c === 201, "$c " . json_encode($d)); $F['b'] = $d['booking']['id'];
  ok((int)$one("SELECT trip_id FROM bookings WHERE id={$F['b']}") === $F['t'], 'link'); return 'booking ' . $F['b'] . ' linked to trip'; });
t('F05 Booking to quote: server total ignores client value; accepted; converted once (idempotent)', function () use (&$F, $one) {
  [$c, $q] = rq('adv', 'POST', '/quotes', ['tripId' => $F['t'], 'title' => 'Kyoto package', 'currency' => 'USD', 'validUntil' => '2027-09-30', 'lines' => [['description' => 'Ryokan (per night)', 'quantity' => '2', 'unitPrice' => '1350.00']], 'total' => '1.00']); ok($c === 201, "quote $c " . json_encode($q)); $F['q'] = $q['quote']['id'];
  ok($q['quote']['total'] === '2700.00' || $one("SELECT total FROM quotations WHERE id={$F['q']}") === '2700.00', 'server total ' . json_encode($q['quote']['total']));
  rq('adv', 'POST', "/quotes/{$F['q']}/send", ['channel' => 'Emailed from advisor mailbox']); [$c2] = rq('adv', 'POST', "/quotes/{$F['q']}/decision", ['decision' => 'accepted', 'clientName' => 'Daniel Shah', 'note' => 'Accepted by phone']); ok($c2 === 200, "decision $c2");
  $k = 'flow-' . bin2hex(random_bytes(6)); [$c3, $i1] = rq('adv', 'POST', "/quotes/{$F['q']}/convert", null, ["Idempotency-Key: $k"]); [$c4, $i2] = rq('adv', 'POST', "/quotes/{$F['q']}/convert", null, ["Idempotency-Key: $k"]); ok($c3 === 200 && $c4 === 200 && $i1["invoice"]["id"] === $i2["invoice"]["id"], "convert $c3 $c4"); $F['i'] = $i1['invoice']['id'];
  ok((int)$one("SELECT COUNT(*) FROM invoices WHERE quote_id={$F['q']}") === 1, 'one invoice'); return 'quote total 2700.00 (client sent 1.00); accepted; one invoice ' . $F['i']; });
t('F06 Invoice issued; payment recorded; retry not duplicated; overpayment refused; manual label', function () use (&$F, $one) { [$c, $d] = rq('adv', 'POST', "/invoices/{$F['i']}/issue", ['dueDate' => '2027-10-01']); ok($c === 200 && preg_match('/^INV-\d{4}-\d{5}$/', $d['invoice']['number']), "issue $c " . json_encode($d)); $F['no'] = $d['invoice']['number'];
  $k = 'pay-' . bin2hex(random_bytes(6)); [$p1, $x] = rq('fin', 'POST', '/payments', ['invoiceId' => $F['i'], 'amount' => '1000.00', 'method' => 'bank_transfer', 'reference' => 'WIRE-FLOW-1'], ["Idempotency-Key: $k"]); [$p2] = rq('fin', 'POST', '/payments', ['invoiceId' => $F['i'], 'amount' => '1000.00', 'method' => 'bank_transfer', 'reference' => 'WIRE-FLOW-1'], ["Idempotency-Key: $k"]);
  [$p3] = rq('fin', 'POST', '/payments', ['invoiceId' => $F['i'], 'amount' => '2000.00', 'method' => 'cash']); $bal = $one("SELECT balance FROM invoices WHERE id={$F['i']}"); $np = (int)$one("SELECT COUNT(*) FROM payments WHERE invoice_id={$F['i']}");
  $ver = $one("SELECT verification FROM payments WHERE invoice_id={$F['i']} LIMIT 1");
  ok($p1 === 201 && in_array($p2, [200, 201], true) && $p3 === 422 && $bal === '1700.00' && $np === 1 && stripos((string)$ver, 'processor') === false, json_encode([$p1, $p2, $p3, $bal, $np, $ver])); return "{$F['no']}; balance 1700.00 after 1000.00; retry replayed (1 payment row); 2000.00 overpayment 422; payment status '$ver'"; });
t('F07 Financial audit chain verifies after the flow', function () { [$c, $d] = rq('own', 'GET', '/finance/audit/verify'); ok($c === 200 && ($d['valid'] ?? false) === true, json_encode($d)); return 'hash chain intact (' . ($d['checked'] ?? '?') . ' events)'; });
t('F08 Call to CRM follow-up: missed call, callback, task', function () use (&$F, $shah, $one) { [$c, $d] = rq('adv', 'POST', '/calls', ['direction' => 'inbound', 'status' => 'missed', 'contactId' => $shah, 'tripId' => $F['t']]); ok($c === 201, "call $c");
  $tz = new DateTimeZone('America/New_York'); [$c2, $cb] = rq('adv', 'POST', '/callbacks', ['callId' => $d['call']['id'], 'scheduledAt' => (new DateTime('+1 day', $tz))->format('Y-m-d\TH:i')]); ok($c2 === 201, "callback $c2");
  ok($one("SELECT CONCAT(t.title,'|',t.trip_id) FROM tasks t WHERE t.id={$cb['callback']['taskId']}") === "Call back Daniel Shah|{$F['t']}", 'task'); return 'missed call -> callback -> task linked to the trip'; });
t('F09 Workflow event to notification and task via the real worker', function () use (&$F, $worker, $one, $adv) { [, $w] = rq('own', 'POST', '/workflows', ['name' => 'Flow booked', 'triggerType' => 'trip.status_changed', 'conditions' => [['field' => 'event.to', 'op' => 'eq', 'value' => 'Booked']], 'actions' => [['type' => 'notify', 'params' => ['to' => 'entity_owner', 'message' => '{{trip.name}} booked', 'category' => 'new_booking']], ['type' => 'create_task', 'params' => ['title' => 'Send documents for {{trip.name}}', 'assignTo' => 'entity_owner']]]]);
  rq('own', 'POST', '/workflows/' . $w['workflow']['id'] . '/enable'); [, $g] = rq('adv', 'GET', "/trips/{$F['t']}"); [$c] = rq('adv', 'PUT', "/trips/{$F['t']}", ['status' => 'Booked', 'version' => $g['trip']['version']]); ok($c === 200, "status $c"); $worker();
  ok((int)$one("SELECT COUNT(*) FROM notifications WHERE user_id=$adv AND message='Kyoto Autumn Flow booked'") === 1 && (int)$one("SELECT COUNT(*) FROM tasks WHERE title='Send documents for Kyoto Autumn Flow' AND assigned_to=$adv") === 1, 'outputs'); return 'notification and task for the trip owner'; });
t('F10 Client sees the published itinerary without internal notes; another client cannot; no invoices in the portal', function () use (&$F) { [$c] = rq('adv', 'POST', "/trips/{$F['t']}/publish"); ok($c === 200, "publish $c"); [, $l] = rq('trv', 'GET', '/portal/trips'); ok(in_array($F['t'], array_column($l['items'] ?? $l['trips'] ?? [], 'id')), 'not listed');
  [$c1, , $raw] = rq('trv', 'GET', "/portal/trips/{$F['t']}"); [$c2] = rq('trv2', 'GET', "/portal/trips/{$F['t']}"); [$c3] = rq('trv', 'GET', "/invoices/{$F['i']}");
  ok($c1 === 200 && strpos($raw, 'Fushimi Inari') !== false && strpos($raw, 'INTERNAL margin') === false && $c2 === 404 && in_array($c3, [403, 404], true), "$c1 $c2 $c3"); return 'client 200 with itinerary, internal note absent; other client 404; invoice ' . $c3; });
t('F11 Everything survives logout and a new login', function () use (&$F) { rq('adv', 'POST', '/auth/logout'); login('adv', 'advisor@lti.test'); foreach (["/contacts/{$F['c']}", "/trips/{$F['t']}", "/bookings/{$F['b']}", "/quotes/{$F['q']}", "/invoices/{$F['i']}"] as $p) { [$c] = rq('adv', 'GET', $p); ok($c === 200, "$p $c"); } return 'contact, trip, booking, quote, invoice re-read in a new session'; });
$pass = count(array_filter($results, fn($r) => $r[1] === true)); foreach ($results as [$n, $o, $d]) echo ($o === true ? 'PASS ' : ($o === null ? 'NOT RUN ' : 'FAIL ')) . "$n — $d\n"; echo "SYSTEM FLOW SUMMARY $pass/" . count($results) . "\n";
file_put_contents(__DIR__ . '/api_system_flow_results.json', json_encode($results, JSON_PRETTY_PRINT)); exit($pass === count($results) ? 0 : 1);
